#include <bits/stdc++.h>
using namespace std;
# define ll long long 
int main() {
	// your code goes here
    int t;cin>>t;
    while(t--)
    {
        int n;cin>>n;
        priority_queue<ll>pq;
        for(int i=0,v;i<3*n;i++)
        {
            cin>>v;
            pq.push(v);
        }
        vector<ll>a,b;
        b.push_back(0);
        while(!pq.empty())
        {
            a.push_back(pq.top());
            b.push_back(b.back()+pq.top());
            pq.pop();
        }
        vector<int>v(n+1);
        iota(v.begin(), v.end(), 0);
        priority_queue<tuple<ll>>q;
        for(int x=0;x<=n;x++)
        {
            int r=n-x;
            auto it=lower_bound(v.begin(),v.begin()+r,0,[&](int y,int){
                return a[x+2*y]+a[x+2*y+1]>a[3*n-2*x-y-1]*3LL;
            });
            int o=*it;
            int s=o>0?o-1:0;
            int e=o<r?o+1:r;
            for(int y=s;y<=e;y++)
            {
                ll ele=2*b[x]+b[x+2*y]+b[3*n-2*x-y]*3LL;
                q.push({ele});
            }
        }
        cout<<get<0>(q.top())<<"\n";
    }
}
